#!/usr/bin/env node
/**
 * Generate docs/parity-checklist.md from the feature parity matrix
 * (frontend/src/utils/featureParityMatrix.js).
 *
 * Usage:  node scripts/generate-parity-checklist.mjs
 *
 * Run after changing the matrix; the generated file is committed so the
 * checklist is readable on GitHub without building the frontend.
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const { FEATURE_PARITY } = await import(
  join(root, 'frontend/src/utils/featureParityMatrix.js')
);

const ICON = { ok: '✅', partial: '⚠️', gap: '❌', na: '—' };

const lines = [
  '# NLE Preview / Export Parity Checklist',
  '',
  '> Generated by `scripts/generate-parity-checklist.mjs` from',
  '> `frontend/src/utils/featureParityMatrix.js` — edit the matrix, not this file.',
  '> Structure and coverage are enforced by `featureParityMatrix.test.js`.',
  '',
  '| Legend | Meaning |',
  '|---|---|',
  '| ✅ | renders/applies on this path |',
  '| ⚠️ | applies with a documented caveat |',
  '| ❌ | known gap on this path |',
  '| — | not applicable |',
  '',
  '| Feature | Panel | Preview | Client export | Server export | Notes |',
  '|---|---|:-:|:-:|:-:|---|',
];

for (const f of FEATURE_PARITY) {
  lines.push(
    `| ${f.label} (\`${f.key}\`) | ${f.panel} | ${ICON[f.preview]} | ` +
    `${ICON[f.clientExport]} | ${ICON[f.serverExport]} | ${f.notes || ''} |`
  );
}

lines.push(
  '',
  '## Pixel-level verification',
  '',
  'The table above is the feature-level contract. For pixel-level checks',
  'between the client canvas export and the server FFmpeg export, run the',
  'frame-compare harness on a machine with FFmpeg (e.g. the Unraid host):',
  '',
  '```bash',
  'make parity CLIENT=client_export.mp4 SERVER=server_export.mp4',
  '# equivalent to:',
  'python scripts/parity_harness.py client_export.mp4 server_export.mp4 \\',
  '    --timestamps 1.0 2.5 5.0 --ssim-threshold 0.90',
  '```',
  '',
  'It extracts frames at the given timestamps from both renders, reports',
  'per-frame SSIM and subtitle bounding-box position/size deltas, and exits',
  'non-zero when any frame falls below the threshold. Known acceptable',
  'divergence sources: libass vs canvas font metrics (a few px), xfade',
  'easing vs canvas cubic-bezier during transitions, and pitch handling of',
  'speed changes (varispeed vs atempo — audio only).',
  ''
);

const out = join(root, 'docs/parity-checklist.md');
writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${out} (${FEATURE_PARITY.length} features)`);
